contract_status"><input type="hidden" name="employee_id" value="<?= $eid ?>"><input type="hidden" name="contract_id" value="<?= (int)$c['id'] ?>"><input type="hidden" name="status" value="terminated"><button class="btn danger" type="submit">إنهاء</button></form><?php endif;?><?php if($c['contract_file_path']):?><a class="btn light" target="_blank" href="<?= e(APP_URL.$c['contract_file_path']) ?>"><i class="fas fa-paperclip"></i></a><?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div><div class="info"><strong>حالة التوظيف:</strong> <?= e($emp['state_name']?:'غير محددة') ?> — تفعيل عقد بدأ بالفعل يضبط «فترة تجربة» إذا كانت فترة التجربة مستمرة، وإلا «على رأس العمل». إنهاء العقد يسجل «منهي الخدمة».</div>
